style.css:
/* DARK ABYSS — Custom Chrome Theme */

:root {
  color-scheme: dark !important;
  --abyss-bg: #08090d;
  --abyss-panel: #11121a;
  --abyss-hover: #1b1b29;
  --abyss-accent: #9b70ff;
  --abyss-text: #e8e5f0;
}

/* Main background */
html, body {
  background-color: var(--abyss-bg) !important;
  color: var(--abyss-text) !important;
}

/* General surfaces */
div, section, article, aside, nav {
  scrollbar-color: #514078 #0b0b11;
}

/* Inputs */
input, textarea, select {
  background: #14141e !important;
  color: #eee9ff !important;
  border: 1px solid #302641 !important;
  border-radius: 9px !important;
}

/* Buttons */
button {
  border-radius: 9px !important;
  transition: 0.2s ease !important;
}

button:hover {
  border-color: var(--abyss-accent) !important;
  box-shadow: 0 0 12px #9b70ff35 !important;
}

/* Links */
a {
  color: #b69aff !important;
  transition: 0.2s ease;
}

a:hover {
  color: #d3bdff !important;
}

/* Selection */
::selection {
  background: #7950c9 !important;
  color: white !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

::-webkit-scrollbar-track {
  background: #090a0f;
}

::-webkit-scrollbar-thumb {
  background: #393047;
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: #8b65d4;
}

/* Subtle dark atmosphere */
body {
  background-image:
    radial-gradient(
      ellipse at 15% 10%,
      #39205a25 0%,
      transparent 45%
    ),
    radial-gradient(
      ellipse at 85% 90%,
      #25164a20 0%,
      transparent 40%
    ) !important;
}
